function patternLetterCrown(n) {
  let rows = [];
  for (let i = 1; i <= n; i++) {
    let row = '';
    for (let j = 0; j < i; j++) row += String.fromCharCode(65 + j);
    for (let j = 0; j < 2 * (n - i); j++) row += ' ';
    for (let j = i - 1; j >= 0; j--) row += String.fromCharCode(65 + j);
    rows.push(row);
  }
  return rows.join('\n');
}

