function patternLetterCrown(n) {
  let rows = [];
  let left = '';
  let right = '';
  for (let i = 1; i <= n; i++) {
    const char = String.fromCharCode(65 + i - 1);
    left += char;
    right = char + right;
    const spaces = ' '.repeat(2 * (n - i));
    rows.push(left + spaces + right);
  }
  return rows.join('\n');
}
